  9	import com.pousadamarealta.service.ReportService;
 10	import com.pousadamarealta.service.ReservationService;
 11	import com.pousadamarealta.web.MessageController;
 12	import com.pousadamarealta.web.ReportController;
 13	import com.pousadamarealta.web.ReservationController;
 14	import com.pousadamarealta.web.RoomController;
 15	import io.javalin.Javalin;
 16	import io.javalin.json.JavalinJackson;
 17	import org.postgresql.ds.PGSimpleDataSource;
 18	
 19	import javax.sql.DataSource;
 20	import java.util.ArrayList;
 21	import java.util.List;
 22	
 23	public class App {
 24	    public static void main(String[] args) {
 25	        DataSource dataSource = createDataSource();
 26	
 27	        DatabaseInitializer dbInitializer = new DatabaseInitializer(dataSource);
 28	        dbInitializer.initialize();
 29	
 30	        RoomRepository roomRepository = new RoomRepository(dataSource);
 31	        ReservationRepository reservationRepository = new ReservationRepository(dataSource);
 32	        MessageRepository messageRepository = new MessageRepository(dataSource);
 33	
 34	        MessageProcessor messageProcessor = createMessageProcessor();
 35	        MessageService messageService = new MessageService(messageRepository, messageProcessor);
 36	        ReservationService reservationService = new ReservationService(
 37	                reservationRepository, roomRepository, messageService);
 38	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 39	
 40	        RoomController roomController = new RoomController(roomRepository);
 41	        ReservationController reservationController = new ReservationController(reservationService, roomRepository);
 42	        MessageController messageController = new MessageController(messageService);
 43	        ReportController reportController = new ReportController(reportService);
 44	
 45	        ObjectMapper objectMapper = new ObjectMapper()
 46	                .registerModule(new JavaTimeModule())
 47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 48	
 49	        int port = getPort();
 50	
 51	        Javalin app = Javalin.create(config -> {
 52	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 53	        }).start(port);
 54	
 55	        app.get("/rooms", roomController::listRooms);
 56	        app.post("/reservations", reservationController::createReservation);
 57	        app.get("/reservations/{id}", reservationController::getReservation);
 58	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 59	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 60	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 61	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 62	        app.get("/reservations/{id}/document", reservationController::getDocument);
 63	        app.get("/messages", messageController::listMessages);
 64	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 65	        app.get("/reports/revenue", reportController::getRevenueReport);
 66	    }
 67	
 68	    private static DataSource createDataSource() {
 69	        String dbUrl = System.getenv("DB_URL");
 70	        String dbUser = System.getenv("DB_USER");
 71	        String dbPassword = System.getenv("DB_PASSWORD");
 72	
 73	        if (dbUrl == null || dbUser == null || dbPassword == null) {
 74	            throw new IllegalStateException("Database configuration missing. " +
 75	                    "Set DB_URL, DB_USER, and DB_PASSWORD environment variables.");
 76	        }
 77	
 78	        PGSimpleDataSource dataSource = new PGSimpleDataSource();
 79	        String jdbcUrl = dbUrl.replace("jdbc:", "");
 80	        dataSource.setUrl(dbUrl);
 81	        dataSource.setUser(dbUser);
 82	        dataSource.setPassword(dbPassword);
 83	
 84	        return dataSource;
 85	    }
 86	
 87	    private static MessageProcessor createMessageProcessor() {
 88	        List<MessageRule> rules = new ArrayList<>();
 89	
 90	        rules.add(new EmailValidationRule());
 91	
 92	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 93	        if (testMode) {
 94	            rules.add(new TestModeRule());
 95	        } else {
 96	            rules.add(new ArchiveCopyRule());
 97	        }
 98	
 99	        return new MessageProcessor(rules);
100	    }
101	
102	    private static int getPort() {
103	        String portEnv = System.getenv("PORT");
104	        if (portEnv != null && !portEnv.isEmpty()) {
105	            return Integer.parseInt(portEnv);
106	        }
107	        return 7070;
108	    }
109	}
