186	package com.pousadamarealta.web;
187	
188	import com.pousadamarealta.domain.RatePlan;
189	import com.pousadamarealta.domain.Reservation;
190	import com.pousadamarealta.domain.Room;
191	import com.pousadamarealta.repository.RoomRepository;
192	import com.pousadamarealta.service.ReservationService;
193	import com.pousadamarealta.web.dto.CreateReservationRequest;
194	import com.pousadamarealta.web.dto.DocumentResponse;
195	import com.pousadamarealta.web.dto.ErrorResponse;
196	import com.pousadamarealta.web.dto.ReservationResponse;
197	import io.javalin.http.Context;
198	
199	import java.time.LocalDate;
200	import java.time.format.DateTimeParseException;
201	
202	public class ReservationController {
203	    private final ReservationService reservationService;
204	    private final RoomRepository roomRepository;
205	
206	    public ReservationController(ReservationService reservationService, RoomRepository roomRepository) {
207	        this.reservationService = reservationService;
208	        this.roomRepository = roomRepository;
209	    }
210	
211	    public void createReservation(Context ctx) {
212	        try {
213	            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
214	
215	            if (request.roomNumber() == null || request.guestName() == null ||
216	                    request.guestEmail() == null || request.guestCpf() == null ||
217	                    request.checkIn() == null || request.checkOut() == null ||
218	                    request.guests() == null || request.ratePlan() == null) {
219	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
220	                return;
221	            }
222	
223	            LocalDate checkIn;
224	            LocalDate checkOut;
225	            try {
226	                checkIn = LocalDate.parse(request.checkIn());
227	                checkOut = LocalDate.parse(request.checkOut());
228	            } catch (DateTimeParseException e) {
229	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
230	                return;
231	            }
232	
233	            if (!checkOut.isAfter(checkIn)) {
234	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
235	                return;
236	            }
237	
238	            if (request.guests() < 1) {
239	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "At least one guest is required"));
240	                return;
241	            }
242	
243	            RatePlan ratePlan;
244	            try {
245	                ratePlan = RatePlan.valueOf(request.ratePlan());
246	            } catch (IllegalArgumentException e) {
247	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
248	                return;
249	            }
250	
251	            Reservation reservation = reservationService.create(
252	                    request.roomNumber(),
253	                    request.guestName(),
254	                    request.guestEmail(),
255	                    request.guestCpf(),
256	                    checkIn,
257	                    checkOut,
258	                    request.guests(),
259	                    ratePlan
260	            );
261	
262	            ctx.status(201).json(ReservationResponse.from(reservation));
263	
264	        } catch (ReservationService.RoomNotFoundException e) {
265	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
266	        } catch (ReservationService.CapacityExceededException e) {
267	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
268	        } catch (ReservationService.RoomUnavailableException e) {
269	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
270	        } catch (Exception e) {
271	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request body"));
272	        }
273	    }
274	
275	    public void getReservation(Context ctx) {
276	        try {
277	            Long id = Long.parseLong(ctx.pathParam("id"));
278	            Reservation reservation = reservationService.findById(id);
279	            ctx.json(ReservationResponse.from(reservation));
280	        } catch (NumberFormatException e) {
281	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
282	        } catch (ReservationService.ReservationNotFoundException e) {
283	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
284	        }
285	    }
286	
287	    public void confirmReservation(Context ctx) {
288	        try {
289	            Long id = Long.parseLong(ctx.pathParam("id"));
290	            Reservation reservation = reservationService.confirm(id);
291	            ctx.json(ReservationResponse.from(reservation));
292	        } catch (NumberFormatException e) {
293	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
294	        } catch (ReservationService.ReservationNotFoundException e) {
295	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
296	        } catch (ReservationService.OperationNotAllowedException e) {
297	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
298	        }
299	    }
300	
301	    public void cancelReservation(Context ctx) {
302	        try {
303	            Long id = Long.parseLong(ctx.pathParam("id"));
304	            Reservation reservation = reservationService.cancel(id);
305	            ctx.json(ReservationResponse.from(reservation));
306	        } catch (NumberFormatException e) {
307	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
308	        } catch (ReservationService.ReservationNotFoundException e) {
309	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
310	        } catch (ReservationService.OperationNotAllowedException e) {
311	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
312	        }
313	    }
314	
315	    public void checkIn(Context ctx) {
316	        try {
317	            Long id = Long.parseLong(ctx.pathParam("id"));
318	            Reservation reservation = reservationService.checkIn(id);
319	            ctx.json(ReservationResponse.from(reservation));
320	        } catch (NumberFormatException e) {
321	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
322	        } catch (ReservationService.ReservationNotFoundException e) {
323	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
324	        } catch (ReservationService.OperationNotAllowedException e) {
325	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
326	        }
327	    }
328	
329	    public void checkOut(Context ctx) {
330	        try {
331	            Long id = Long.parseLong(ctx.pathParam("id"));
332	            Reservation reservation = reservationService.checkOut(id);
333	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
334	            ctx.json(DocumentResponse.from(reservation, room));
335	        } catch (NumberFormatException e) {
336	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
337	        } catch (ReservationService.ReservationNotFoundException e) {
338	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
339	        } catch (ReservationService.OperationNotAllowedException e) {
340	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
341	        }
342	    }
343	
344	    public void getDocument(Context ctx) {
345	        try {
346	            Long id = Long.parseLong(ctx.pathParam("id"));
347	            Reservation reservation = reservationService.findById(id);
348	
349	            if (!reservation.isPaid()) {
350	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED",
351	                        "Document is only available for paid reservations"));
352	                return;
353	            }
354	
355	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
356	            ctx.json(DocumentResponse.from(reservation, room));
357	        } catch (NumberFormatException e) {
358	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid reservation ID"));
359	        } catch (ReservationService.ReservationNotFoundException e) {
360	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
361	        }
362	    }
363	}
