     5	public class EmailValidationRule implements MessageRule {
     6	    @Override
     7	    public void apply(ProcessedMessage message) {
     8	        if (!isValidEmail(message.getTo())) {
     9	            message.setStatus(MessageStatus.BLOCKED);
    10	        }
    11	    }
    12	
    13	    private boolean isValidEmail(String email) {
    14	        if (email == null || email.isEmpty()) {
    15	            return false;
    16	        }
    17	
    18	        long atCount = email.chars().filter(ch -> ch == '@').count();
    19	        if (atCount != 1) {
    20	            return false;
    21	        }
    22	
    23	        int atIndex = email.indexOf('@');
    24	        if (atIndex == 0) {
    25	            return false;
    26	        }
    27	
    28	        String afterAt = email.substring(atIndex + 1);
    29	        if (afterAt.isEmpty()) {
    30	            return false;
    31	        }
    32	
    33	        return afterAt.contains(".");
    34	    }
    35	}
