    22	                        type VARCHAR(20) NOT NULL
    23	                    )
    24	                    """);
    25	
    26	            stmt.execute("""
    27	                    CREATE TABLE IF NOT EXISTS reservations (
    28	                        id BIGSERIAL PRIMARY KEY,
    29	                        room_number VARCHAR(10) NOT NULL,
    30	                        guest_name VARCHAR(255) NOT NULL,
    31	                        guest_email VARCHAR(255) NOT NULL,
