    41	                        status VARCHAR(20) NOT NULL,
    42	                        amount_paid DECIMAL(10, 2) NOT NULL,
    43	                        refund DECIMAL(10, 2),
    44	                        FOREIGN KEY (room_number) REFERENCES rooms(number)
    45	                    )
    46	                    """);
    47	
    48	            stmt.execute("""
    49	                    CREATE TABLE IF NOT EXISTS messages (
